const TRADE_TYPES = ['직매입', '위탁판매', '제휴입점'];
// 계약 묶음 구성: K1은 기본계약 + 거래형태 부속서 + 별지 1 (+ 별지 3)
function kindParts(kind, trade, opt) {
  const k = CONTRACT_KINDS[kind];
  if (!k) return [];
  if (kind !== 'K1') return k.docs.slice();
  opt = opt || {};
  const parts = ['BASE'];
  if (trade === '직매입') { if (opt.A) parts.push('A'); if (opt.B) parts.push('B'); }
  else if (trade === '위탁판매') parts.push('C');
  else if (trade === '제휴입점') parts.push('D');
  parts.push('S1');
  if (opt.S3) parts.push('S3');
  return parts;
}
function partsKeys(parts) {
  const out = [];
  parts.forEach(function (p) { (CONTRACT_DOCS[p] ? CONTRACT_DOCS[p].keys : []).forEach(function (k) { if (out.indexOf(k) < 0) out.push(k); }); });
  return out;
}
function fmtComma(v) {
  const d = String(v === undefined || v === null ? '' : v).replace(/[^0-9]/g, '');
  return d ? Number(d).toLocaleString('en-US') : '';
}
// 제휴입점 광고료: 일 단가 × 게재 일수 − 장기 게재 할인
function adRate(days) { return days >= 365 ? 0.2 : days >= 180 ? 0.15 : days >= 90 ? 0.1 : days >= 30 ? 0.05 : 0; }
function adCalc(start, end, unit) {
  const re = /^\d{4}-\d{2}-\d{2}$/;
  if (!re.test(String(start || '')) || !re.test(String(end || ''))) return null;
  const s = Date.UTC(+start.slice(0, 4), +start.slice(5, 7) - 1, +start.slice(8, 10));
  const e = Date.UTC(+end.slice(0, 4), +end.slice(5, 7) - 1, +end.slice(8, 10));
  if (e < s) return null;
  const days = Math.round((e - s) / 86400000) + 1;
  const u = Number(String(unit || '').replace(/[^0-9]/g, '')) || 0;
  const rate = adRate(days);
  return { days: days, rate: rate, gross: u * days, total: Math.round(u * days * (1 - rate)) };
}
// 별지 1 거래조건표: 공급사의 거래형태에 맞는 표를 상품 데이터로 만듭니다.
function termsTable(trade, products, values) {
  values = values || {};
  const w = function (n) { const s = fmtComma(n); return s ? s + '원' : ''; };
  const nm = function (p) { return p['상품명'] + (p['규격'] ? ' · ' + p['규격'] : ''); };
  const list = (products || []).filter(function (p) { return p['상태'] !== '판매중지'; });
  if (trade === '위탁판매') {
    return { title: '위탁판매 상품', head: ['상품코드', '상품명 · 규격', '과세 구분', '일반회원가 (VAT 포함)', '구독회원가 (VAT 포함)', '수수료율', '배송방식'],
      rows: list.map(function (p) { return [p.id, nm(p), p['과세구분'] || '', w(p['일반회원가']), w(p['구독회원가']), (p['수수료율'] || values['수수료율'] || '') + '%', p['배송방식'] || '']; }) };
  }
  if (trade === '제휴입점') {
    return { title: '제휴입점 광고 상품', head: ['상품코드', '상품명', '게재 위치', '일 단가 (VAT 별도)', '게재 기간', '연결 주소', '회원 전용 혜택'],
      rows: list.map(function (p) { return [p.id, p['상품명'], values['광고_게재위치'] || '', values['광고_일단가'] ? values['광고_일단가'] + '원' : '', values['광고_게재일수'] ? values['광고_게재일수'] + '일' : '', p['연결주소'] || '', p['회원혜택'] || '']; }) };
  }
  return { title: '직매입 상품', head: ['상품코드', '상품명 · 규격', '배송방식', '과세 구분', '공급가 (VAT 별도)', '발주·출고 조건', '배송비'],
    rows: list.map(function (p) {
      return [p.id, nm(p), p['배송방식'] || '', p['과세구분'] || '', w(p['공급가']), p['거래조건'] || '',
        p['배송비부담'] || (p['배송방식'] === '업체배송' ? '공급가에 포함' : '납품 운송비 공급하는 자 부담')];
    }) };
}
